#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.."&&pwd);OUT=$ROOT/work/results/l5_q128_oproj;R=$ROOT/scripts/run_memory_capped.sh;V=$ROOT/work/toolchain/conda/bin/verilator;PY=$ROOT/work/toolchain/cnn_py312/bin/python;mkdir -p "$OUT"
for b in 0 1 2 3 4 5 6 7;do mkdir -p "$OUT/batch$b";taskset -c 8-23 "$PY" "$ROOT/scripts/generate_l5_q128_oproj_batch_vectors.py" --attention "$ROOT/work/results/l5_q128_mlo/vectors/attention.memh" --inputs "$ROOT/work/results/l5_q128_qkv/shared/inputs.memh" --weights "$ROOT/work/results/l5_target_oproj/vectors/weights_bf16.memh" --norm-weight "$ROOT/work/results/l5_target_norm2/vectors/weight.memh" --tokens 128 --batch-index "$b" --out "$OUT/batch$b";done
S=("$ROOT/work/generated/l5_all_primitives/HeteroAllPrimitives.sv" "$ROOT/rtl/matrix/bf16_outer_product_array.sv" "$ROOT/rtl/sfu/fp32_vector_alu.sv" "$ROOT/rtl/sfu/fp32_reduce16.sv" "$ROOT/rtl/sfu/fp32_rsqrt_nr.sv" "$ROOT/rtl/sfu/fp32_rmsnorm1536_chunked.sv" "$ROOT/tb/tb_l5_q128_oproj_batch.sv")
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$V" --lint-only --timing -Wall -Wno-DECLFILENAME -Wno-TIMESCALEMOD -Wno-UNUSEDSIGNAL --top-module tb_l5_q128_oproj_batch "${S[@]}" >"$OUT/lint.log" 2>&1
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$V" --binary --timing -Wall -Wno-DECLFILENAME -Wno-TIMESCALEMOD -Wno-UNUSEDSIGNAL -j 8 -MAKEFLAGS "AR=/usr/bin/ar CXX=/usr/bin/g++" --top-module tb_l5_q128_oproj_batch --Mdir "$OUT/obj" -o tb "${S[@]}" >"$OUT/build.log" 2>&1
cd "$ROOT";for b in 0 1 2 3 4 5 6 7;do MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$OUT/obj/tb" +WORKLOAD=128 +BATCH="$b"|tee "$OUT/batch$b/tb.log";grep -q "L5_Q_PREFILL_OPROJ_BATCH_PASS workload=128 batch=$b" "$OUT/batch$b/tb.log";done;echo L5_Q128_OPROJ_ALL_BATCHES_GATE_PASS
